mapper.select:
SELECT instance.instance_id AS id, instance.title, instance.process_no AS number, instance.status FROM wf_process_instance instance WHERE instance.tenant_id = #{tenantId} AND instance.deleted = 0 AND (instance.title LIKE #{pattern} ESCAPE '!' OR instance.process_no LIKE #{pattern} ESCAPE '!')
AND (instance.start_user_id = #{userId} OR EXISTS(SELECT 1 FROM wf_task task WHERE task.tenant_id = instance.tenant_id AND task.instance_id = instance.instance_id AND task.assignee = #{userId}) OR EXISTS(SELECT 1 FROM wf_task_history history WHERE history.tenant_id = instance.tenant_id AND history.instance_id = instance.instance_id AND (history.operator_id = #{userId} OR history.on_behalf_of_user_id = #{userId})) OR EXISTS(SELECT 1 FROM wf_process_copy copy WHERE copy.tenant_id = instance.tenant_id AND copy.instance_id = instance.instance_id COLLATE utf8mb4_general_ci AND copy.user_id = #{userId})
OR instance.instance_id IN #{instanceId}
)
